<template><AdministrationLayout search-placeholder="Rechercher une zone…" v-slot="{search}"><section class="zones-page"><header class="page-title"><span><AppIcon name="pin" :size="25"/></span><div><h1>Gestion des zones d’intervention</h1><p>Configurez les zones géographiques couvertes par les techniciens.</p></div><button @click="openCreate"><AppIcon name="plus" :size="16"/> Ajouter une Zone</button></header><TableauZones :zones="filtered(search)" @edit="openEdit" @delete="deleteZone"/><footer><span>Affichage de 1 à {{filtered(search).length}} sur {{zones.length}} zones</span><div><button aria-label="Page précédente"><AppIcon name="chevron-left" :size="15"/></button><button class="current">1</button><button aria-label="Page suivante"><AppIcon name="chevron-right" :size="15"/></button></div></footer></section><AjouterZoneModal v-if="modal" :zone="selected" @close="modal=false" @save="save"/></AdministrationLayout></template>
<script setup>import{onMounted,ref}from'vue';import AdministrationLayout from '../../components/administrateur/AdministrationLayout.vue';import TableauZones from '../../components/administrateur/TableauZones.vue';import AjouterZoneModal from '../../modales/administrateur/AjouterZoneModal.vue';import{useZones}from'../../services/serviceZones';const{zones,charger,create,update,remove}=useZones();const modal=ref(false),selected=ref(null);const filtered=search=>{const q=search.toLowerCase();return zones.value.filter(z=>`${z.city} ${z.districts}`.toLowerCase().includes(q))};function openCreate(){selected.value=null;modal.value=true}function openEdit(zone){selected.value=zone;modal.value=true}async function save(data){await (selected.value?update({...selected.value,...data}):create(data));modal.value=false}async function deleteZone(zone){if(window.confirm(`Supprimer la zone de ${zone.city} ?`))await remove(zone.id)}onMounted(charger)</script>
<style scoped>.zones-page{background:#fff;border:1px solid #e1edfa;border-radius:11px;padding:16px;box-shadow:0 4px 20px #114d9710}.page-title{min-height:70px;display:flex;align-items:center;gap:16px;padding:0 0 16px;border-bottom:1px solid #e5effa}.page-title>span{width:55px;height:55px;display:grid;place-items:center;border-radius:13px;background:#e2efff;color:#087f70;font-size:32px}.page-title h1{text-transform:uppercase;font-size:20px;margin:0;color:#174b50}.page-title p{margin:6px 0 0;color:#5274ab;font-size:14px}.page-title button{margin-left:auto;padding:14px 20px;border-radius:9px;background:#087f70;color:#fff;font-size:13px}.zones-page>footer{display:flex;justify-content:space-between;align-items:center;padding:18px 7px 8px;color:#6481b4;font-size:13px}.zones-page footer div{display:flex;gap:10px}.zones-page footer button{width:34px;height:34px;border-radius:8px;border:1px solid #d3e3f7;background:#fff;color:#7290bc}.zones-page footer .current{background:#087f70;color:#fff;border-color:#087f70}@media(max-width:650px){.page-title{align-items:flex-start;flex-wrap:wrap}.page-title h1{font-size:16px}.page-title button{margin-left:70px;margin-top:-5px}.zones-page>footer{font-size:11px}}</style>
